function startTheGame() {
    lastMenu = 'Game';
    const player = document.createElement('div');
    const playerImg = document.createElement('img');
    player.style.width = '150px';
    player.style.height = '150px';
    player.style.position = 'absolute';
    player.style.zIndex = '1000';
    player.style.left = '50%';
    player.style.top = '50%';
    playerImg.style.width = '150px';
    playerImg.style.height = '150px';
    playerImg.src = 'data:image/jpeg;base64,';

    player.appendChild(playerImg);
    document.body.appendChild(player);

    function createGun(gunPosX, gunPosY) {
        const gun = document.createElement('div');
        const gunImg = document.createElement('img');
        gun.style.width = '50px';
        gun.style.height = '50px';
        gun.style.position = 'absolute';
        gun.style.zIndex = '1000';
        gun.style.left = '50%';
        gun.style.top = '50%';
        gunImg.style.width = '50px';
        gunImg.style.height = '50px';
        gunImg.src = 'data:image/jpeg;base64,';

        gun.style.transform = 'translate(' + gunPosX + 'px, ' + gunPosY + 'px)'

        gun.appendChild(gunImg);
        document.body.appendChild(gun);

        return gun;
    }

    function createBullet(posX, posY) {
        const bullet = document.createElement('div');
        const bulletImg = document.createElement('img');
        bullet.style.width = '50px';
        bullet.style.height = '50px';
        bullet.style.position = 'absolute';
        bullet.style.zIndex = '1000';
        bullet.style.left = '50%';
        bullet.style.top = '50%';
        bulletImg.style.width = '50px';
        bulletImg.style.height = '50px';
        bulletImg.src = 'data:image/png;base64,';
        
        bullet.appendChild(bulletImg);
        document.body.appendChild(bullet);

        bullet.pos = [posX, posY]
        bullet.style.transform = 'translate('+ posX +'px, '+ posY +'px)'
        if (playerRotY < 90) {
            bullet.rot = 180;
        }
        else {
            bullet.rot = 0;
        }
        return bullet
    }
    //varibles

    let speedX = 5;
    let speedY = 5;
    let direction = 'n';
    let posX = 0;
    let posY = 0;
    let shootMode = false;
    let lmPosX = 0;
    let playerRotY = 0;
    let l = 0;
    let enemyDrcVal = 2;
    let enemyDrcValY = 2;
    let bulletList = [];
    let gun = createGun(posX, posY + 10000);
    let enemy = [summonEnemy(500), summonEnemy(200)];

    document.addEventListener('keydown', function(e) {
        if (e.key == 'w') {
            direction = 'w';
        }
        if (e.key == 's') {
            direction = 's';
        }
        if (e.key == 'a') {
            direction = 'a';
        }
        if (e.key == 'd') {
            direction = 'd';
        }
        if ((e.key == 'w' || e.key == 's' || e.key == 'a' || e.key == 'd' ) && shootMode == false) {
            playerImg.src = 'data:image/jpeg;base64,';
        }
        if (e.key == 'r' && shootMode == false) {
            shootMode = true;
            gun = createGun(posX, posY);
        }
        else if (e.key == 'r' && shootMode == true) {
            shootMode = false;
            gun.remove()
        }
        if (e.key == 'f' && shootMode == true) {
            bulletList.push(createBullet(posX, posY))
        }
    })
    document.addEventListener('keyup', function(e) {
        if (e.key == 'w' || e.key == 's' || e.key == 'a' || e.key == 'd') {
            direction = 'n';
            playerImg.src = 'data:image/jpeg;base64,';
        }
    })

    document.addEventListener('mousemove', function(e) {
        lmPosX = e.clientX
    })

    //enimes and enyme AI
    function summonEnemy(posX) {
        const enemy = document.createElement('div');
        const enemyImg = document.createElement('img');
        enemy.style.width = '100px';
        enemy.style.height = '50px';
        enemy.style.position = 'absolute';
        enemy.style.zIndex = '1000';
        enemy.style.top = '50%';
        enemy.style.left = '50%';
        enemyImg.style.height = '100px';
        enemyImg.style.width = '50px';
        enemyImg.src = 'data:image/jpeg;base64,';

        enemy.appendChild(enemyImg);
        document.body.appendChild(enemy);

        enemy.style.transform = 'translateX('+ posX +'px)'

        enemy.speed = (Math.round(Math.random() * 10))/10
        enemy.positions = [posX, 0];
        return enemy
    }

    const interval = setInterval(() => {
        if (shootMode == false) {
            playerRotY = 0;
            if (direction == 'w') {
                posY -= speedY
            }
            else if (direction == 's') {
                posY += speedY
            }
            else if (direction == 'a') {
            playerRotY = 180;
                posX -= speedX
            }
            else if (direction == 'd') {
            playerRotY = 0;
                posX += speedX
            }
        }
        else {
            playerRotY = lmPosX/(innerWidth/180)
            gun.style.transform = 'translate('+ ((posX - 20) + lmPosX/(innerWidth/parseInt(player.style.width))) +'px, '+ posY +'px) rotateY('+ playerRotY +'deg)';
        }
        l++;
        if (l >= 2000 && enemy.length < 5) {
            l = 0;
            enemy.push(summonEnemy(600))
        }
        for (const i of enemy) {
            if (posX > i.positions[0]) {
                enemyDrcVal = 1 * i.speed;
            }
            else if (posX < i.positions[0]) {
                enemyDrcVal = -1 * i.speed;
            }
            else {
                enemyDrcVal = 0 * i.speed;
            }

            if (posY > i.positions[1]) {
                enemyDrcValY = 1 * i.speed;
            }
            else if (posY < i.positions[1]) {
                enemyDrcValY = -1 * i.speed;
            }
            else {
                enemyDrcValY = 0 * i.speed;
            }
            for (const b of enemy) {
                if (i != b) {
                    const enemyCol = b.getBoundingClientRect();
                    const Col = i.getBoundingClientRect();
                    if ((enemyCol.left + 40 <= Col.right && enemyCol.right + 40 >= Col.right)) {
                        i.positions[0] -= 40;
                    }
                    if ((enemyCol.right - 40 >= Col.left && enemyCol.left - 40 <= Col.left)) {
                        i.positions[0] += 40;
                    }
                }
            }
            i.style.transform = 'translate('+ (i.positions[0] + enemyDrcVal) +'px, '+ (i.positions[1] + enemyDrcValY) +'px)';
            i.positions[0] += enemyDrcVal
            i.positions[1] += enemyDrcValY
        }
        l++;
        for (i of bulletList) {
            if (i.rot == 0) {
                i.pos[0] += 10;
            }
            if (i.rot == 180) {
                i.pos[0] -= 10;
            }
            i.style.transform = 'translate('+ i.pos[0] +'px, '+ i.pos[1] +'px)';
            if (i.pos[0] >= (posX + 1000)) {
                i.remove();
                bulletList.pop()
            }
        }
        player.style.transform = 'translate('+ posX +'px, '+ posY +'px) rotateY('+ playerRotY +'deg)';
    }, 10);
}

