function startTheMenu() {
    lastMenu = 'Start';
    const startGame = document.createElement('div');
    const startGameImg = document.createElement('img');
    startGame.style.width = '500px';
    startGame.style.height = '200px';
    startGame.style.position = 'absolute';
    startGame.style.zIndex = '1000';
    startGame.style.left = ((window.innerWidth / 2) - (parseInt(startGame.style.width)/2)) + 'px'
    startGame.style.top = '10%';
    startGameImg.style.width = '500px';
    startGameImg.style.height = '200px';
    startGameImg.src = 'data:image/png;base64,';
    startGame.appendChild(startGameImg);
    document.body.appendChild(startGame);

    const setting = document.createElement('div');
    const settingImg = document.createElement('img');
    setting.style.width = '250px';
    setting.style.height = '100px';
    setting.style.position = 'absolute';
    setting.style.zIndex = '1000';
    setting.style.left = ((window.innerWidth / 2) - (parseInt(setting.style.width)/2)) + 'px'
    setting.style.top = '60%';
    settingImg.style.width = '250px';
    settingImg.style.height = '100px';
    settingImg.src = 'data:image/png;base64,';
    setting.appendChild(settingImg);
    document.body.appendChild(setting);

    return [setting, startGame];
}
let stuff = startTheMenu();
let setting = stuff[0];
let startGame = stuff[1];
let stuff2 = null;

document.addEventListener('click', function (e) {
    const sCol = startGame.getBoundingClientRect();
    if (e.clientX >= sCol.left && e.clientX <= sCol.right && e.clientY <= sCol.bottom && e.clientY >= sCol.top) {
        console.log('clicked');
        for (let i = 0; i < 10001; i++) {
            console.log('loading... ' + i/100 +'%')
            if (i == 10000) {
                startTheGame();
                setting.remove();
                startGame.remove();
                stuff = [];
            }
        }
    }
    const seCol = setting.getBoundingClientRect();
    if (e.clientX >= seCol.left && e.clientX <= seCol.right && e.clientY <= seCol.bottom && e.clientY >= seCol.top) {
        console.log('clicked');
        stuff2 = startTheSettingsMenu();
        return stuff2
    }
    let scro1 = stuff2[1];
    let scro2 = stuff2[3];
    let scro3 = stuff2[5];
    let txt1 = stuff2[0];
    let txt2 = stuff2[2];
    let txt3 = stuff2[4];
    const scroCol1 = scro1.getBoundingClientRect();
    const scroCol2 = scro2.getBoundingClientRect();
    const scroCol3 = scro3.getBoundingClientRect();
    if (e.clientX >= scroCol1.left && e.clientX <= scroCol1.right && e.clientY <= scroCol1.bottom && e.clientY >= scroCol1.top) {
        console.log('add one to : 1')
        speed += 1;
        txt1.textContent = 'speed of player = ' + speed;
    }
    if (e.clientX >= scroCol2.left && e.clientX <= scroCol2.right && e.clientY <= scroCol2.bottom && e.clientY >= scroCol2.top) {
        console.log('add one to : 2')

    }
    if (e.clientX >= scroCol3.left && e.clientX <= scroCol3.right && e.clientY <= scroCol3.bottom && e.clientY >= scroCol3.top) {
        console.log('add one to : 3')
    }
})
